16	import type { KitchenPrintJobPayload } from "@/lib/kitchen-print";
17	
18	const SYNC_INTERVAL_MS = 20000;
19	
20	// Dipakai di pos-screen.tsx & ticket-pos-screen.tsx. Melacak status
21	// online/offline browser, menyimpan/membaca antrian penjualan tertunda dari
22	// IndexedDB, dan mencoba sinkronkan ulang otomatis begitu koneksi kembali.
23	// Lihat rencana di plan file untuk kenapa desainnya begini — intinya: retry
24	// harus berurutan (bukan paralel) supaya konflik nomor tiket fisik
25	// terdeteksi satu-satu, dan idempotency (clientRef) di server yang menjamin
26	// retry yang mengulang penjualan yang sebenarnya sudah sukses tidak
27	// membuat transaksi duplikat.
28	export function useOfflineSync(businessId: string) {
29	  const [isOnline, setIsOnline] = useState(
30	    () => typeof navigator === "undefined" || navigator.onLine,
31	  );
32	  const [pending, setPending] = useState<PendingSale[]>([]);
33	  const syncingRef = useRef(false);
34	
35	  const refresh = useCallback(async () => {
36	    const rows = await listPending(businessId);
37	    setPending(rows);
38	    return rows;
39	  }, [businessId]);
40	
41	  const syncNow = useCallback(async () => {
42	    if (syncingRef.current) return;
43	    if (typeof navigator !== "undefined" && !navigator.onLine) return;
44	    syncingRef.current = true;
45	    try {
46	      const rows = await refresh();
47	      for (const sale of rows) {
48	        // Sudah gagal karena alasan bisnis (bukan jaringan) sebelumnya —
49	        // butuh tinjauan manual, jangan di-retry otomatis terus-menerus.
50	        if (sale.status === "error") continue;
51	
52	        await markSyncing(sale);
53	        try {
54	          const result =
55	            sale.kind === "retail"
56	              ? await checkout(
57	                  sale.businessId,
58	                  sale.payload.cashierId,
59	                  sale.payload.items,
60	                  sale.payload.paymentMethod,
61	                  sale.payload.received,
62	                  sale.payload.orderDisc,
63	                  sale.payload.orderDiscType,
64	                  sale.payload.customerId,
65	                  sale.payload.selfOrderIds,
66	                  sale.clientRef,
67	                )
68	              : await checkoutTicket(
69	                  sale.businessId,
70	                  sale.payload.cashierId,
71	                  sale.payload.items,
72	                  sale.payload.paymentMethod,
73	                  sale.payload.received,
74	                  sale.payload.memberId,
75	                  sale.clientRef,
76	                );
77	
78	          if (result.success) {
79	            await markSynced(sale.clientRef);
80	            // Only the "retail" checkout() path returns printJobs —
81	            // checkoutTicket() doesn't do kitchen printing at all.
82	            if (sale.kind === "retail") {
83	              const { printJobs, receiptPrintJobs } = result as unknown as {
84	                printJobs: KitchenPrintJobPayload[];
85	                receiptPrintJobs: KitchenPrintJobPayload[];
86	              };
87	              void dispatchReceiptThenKitchenJobs(sale.businessId, receiptPrintJobs, printJobs);
88	            }
89	          } else {
90	            await markError(sale, result.error);
91	          }
92	        } catch {
93	          // Masih gagal jaringan (timeout/koneksi putus lagi) — kembalikan
94	          // ke "pending", coba lagi di siklus sync berikutnya.
95	          await enqueueSale({ ...sale, status: "pending" });
96	        }
97	      }
98	    } finally {
99	      syncingRef.current = false;
100	      await refresh();
101	    }
102	  }, [refresh]);
103	
104	  const discard = useCallback(
105	    async (clientRef: string) => {
106	      await discardPending(clientRef);
107	      await refresh();
108	    },
109	    [refresh],
110	  );
111	
112	  useEffect(() => {
113	    // Fase 2 (cold-start offline): daftarkan service worker yang cache
114	    // halaman POS + aset statis, supaya reload/buka tab saat benar-benar
115	    // offline masih bisa menampilkan UI terakhir (lihat public/sw.js).
116	    // Idempotent — aman dipanggil di setiap mount/businessId berganti.
117	    if ("serviceWorker" in navigator) {
118	      navigator.serviceWorker
119	        .register("/sw.js", { scope: "/", updateViaCache: "none" })
120	        .catch(() => {});
121	    }
122	  }, []);
123	
124	  useEffect(() => {
125	    listPending(businessId).then(setPending);
126	
127	    function handleOnline() {
128	      setIsOnline(true);
129	      void syncNow();
130	    }
131	    function handleOffline() {
132	      setIsOnline(false);
133	    }
134	
135	    window.addEventListener("online", handleOnline);
136	    window.addEventListener("offline", handleOffline);
137	    return () => {
138	      window.removeEventListener("online", handleOnline);
139	      window.removeEventListener("offline", handleOffline);
140	    };
141	  }, [businessId, syncNow]);
142	
143	  useEffect(() => {
144	    const interval = setInterval(() => {
145	      if (pending.length > 0) void syncNow();
146	    }, SYNC_INTERVAL_MS);
147	    return () => clearInterval(interval);
148	  }, [pending.length, syncNow]);
149	
150	  return { isOnline, pending, syncNow, discard };
151	}
